class Solution {
    public int removeDuplicates(int[] nums) {
        List<Integer> unique = new ArrayList<>();
        for (int x : nums)
            if (unique.isEmpty() || unique.get(unique.size() - 1) != x) unique.add(x);
        for (int i = 0; i < unique.size(); i++) nums[i] = unique.get(i);
        return unique.size();
    }
}

