class Solution:
    def validPalindrome(self, s: str) -> bool:
        def is_pal_skip(skip):
            i, j = 0, len(s) - 1
            while i < j:
                if i == skip:
                    i += 1
                    continue
                if j == skip:
                    j -= 1
                    continue
                if s[i] != s[j]:
                    return False
                i += 1
                j -= 1
            return True
        if is_pal_skip(-1):
            return True
        return any(is_pal_skip(k) for k in range(len(s)))

